export function getToolLocalizedInfo(slug: string, lang: string): LocalizedToolInfo {
  const item = toolTranslations[slug];
  if (!item) {
    return {
      name: slug,
      description: 'Free online tool by ToolAtlas.',
      intro: 'Fast, private, and client-side browser utility.',
      steps: ['Open the tool.', 'Enter or select your data.', 'Execute and download the result.']
    };
  }
  return item[lang] || item.en;
}
